from collections import Counter

def _mode_ratio(vals):
    c=Counter(vals); v,n=c.most_common(1)[0]; return v,n/len(vals)

def transform(grid):
    h,w=len(grid),len(grid[0])
    base=Counter(x for row in grid for x in row).most_common(1)[0][0]
    rowlines=[]
    rowmodes={}
    for r,row in enumerate(grid):
        m,frac=_mode_ratio(row); rowmodes[r]=m
        if m!=base and frac>=0.60: rowlines.append(r)
    if len(rowlines)<2:
        return [[base]]
    line_color=Counter(rowmodes[r] for r in rowlines).most_common(1)[0][0]
    # Vertical separators are either long dominant columns or signal positions on horizontal separator rows.
    cols=[]
    for c in range(w):
        m,frac=_mode_ratio([grid[r][c] for r in range(h)])
        if m!=base and frac>=0.60: cols.append(c)
    for r in rowlines:
        for c,v in enumerate(grid[r]):
            if v!=rowmodes[r]: cols.append(c)
    cols=sorted(set(cols))
    if len(cols)<2: return [[base]]
    # Tile values are the common corner marker when all four corners agree; otherwise use the tile fill.
    out=[]
    for ri in range(len(rowlines)-1):
        row=[]
        for ci in range(len(cols)-1):
            a,b=rowlines[ri],rowlines[ri+1]; x,y=cols[ci],cols[ci+1]
            vals=[grid[a][x],grid[a][y],grid[b][x],grid[b][y]]
            v=vals[0] if len(set(vals))==1 and vals[0]!=line_color else base
            row.append(v)
        out.append(row)
    # Remove all-background margins, but preserve blank rows/columns inside the image.
    while out and all(v==base for v in out[0]): out.pop(0)
    while out and all(v==base for v in out[-1]): out.pop()
    if out:
        while out and all(row[0]==base for row in out):
            for row in out: row.pop(0)
        while out and all(row and row[-1]==base for row in out):
            for row in out: row.pop()
    return out

def build_demo(h,w,rr,cc,base,line,marks):
    g=[[base]*w for _ in range(h)]
    for r in rr:
        g[r]=[line]*w
    for c in cc:
        for r in range(h): g[r][c]=line
    for r,vals in zip(rr,marks):
        for c,v in zip(cc,vals): g[r][c]=v
    return g

