program_source='''from collections import Counter


def _mode_ratio(values):
    counts = Counter(values)
    value, count = counts.most_common(1)[0]
    return value, count / len(values)


def transform(grid):
    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]

    row_lines = []
    row_modes = {}
    for r, row in enumerate(grid):
        mode, fraction = _mode_ratio(row)
        row_modes[r] = mode
        if mode != background and fraction >= 0.60:
            row_lines.append(r)

    if len(row_lines) < 2:
        return [[background]]

    line_color = Counter(row_modes[r] for r in row_lines).most_common(1)[0][0]

    # Find vertical grid lines from dominant columns, and from marked points
    # along the horizontal grid lines when verticals are otherwise invisible.
    columns = []
    for c in range(width):
        mode, fraction = _mode_ratio([grid[r][c] for r in range(height)])
        if mode != background and fraction >= 0.60:
            columns.append(c)
    for r in row_lines:
        for c, value in enumerate(grid[r]):
            if value != row_modes[r]:
                columns.append(c)
    columns = sorted(set(columns))

    if len(columns) < 2:
        return [[background]]

    # A tile keeps a special color only when all four corner marks agree.
    output = []
    for ri in range(len(row_lines) - 1):
        output_row = []
        for ci in range(len(columns) - 1):
            top, bottom = row_lines[ri], row_lines[ri + 1]
            left, right = columns[ci], columns[ci + 1]
            corners = [grid[top][left], grid[top][right],
                       grid[bottom][left], grid[bottom][right]]
            if corners.count(corners[0]) == 4 and corners[0] != line_color:
                output_row.append(corners[0])
            else:
                output_row.append(background)
        output.append(output_row)

    # Trim only all-background margins; blank rows and columns inside remain.
    while output and all(value == background for value in output[0]):
        output.pop(0)
    while output and all(value == background for value in output[-1]):
        output.pop()
    if output:
        while output and all(row[0] == background for row in output):
            for row in output:
                row.pop(0)
        while output and all(row and row[-1] == background for row in output):
            for row in output:
                row.pop()
    return output
'''
